            <Select allowClear options={flattenDepartmentOptions(departments)} />
          </Form.Item>
          <Form.Item label="所属平台" name="platform_id">
            <Select allowClear options={platforms.map((item) => ({ label: item.name, value: item.id }))} />
          </Form.Item>
